function countSpecialNumbers(n) {
  const digits = String(n).split('').map(Number);
  const memo = new Map();

  function count(pos, mask, tight, started) {
    if (pos === digits.length) {
      return started ? 1 : 0;
    }
    const reusable = !tight && started;
    const key = pos * 1024 + mask;
    if (reusable && memo.has(key)) {
      return memo.get(key);
    }
    const limit = tight ? digits[pos] : 9;
    let total = 0;
    for (let digit = 0; digit <= limit; digit++) {
      const nextTight = tight && digit === limit;
      if (!started && digit === 0) {
        total += count(pos + 1, mask, nextTight, false);
      } else if ((mask & (1 << digit)) === 0) {
        total += count(pos + 1, mask | (1 << digit), nextTight, true);
      }
    }
    if (reusable) {
      memo.set(key, total);
    }
    return total;
  }

  return count(0, 0, true, false);
}

