function countSpecialNumbers(n) {
  // List every number with distinct digits by appending unused digits, and count those that do not exceed n.
  const used = new Array(10).fill(false);
  let total = 0;
  const extend = (value) => {
    total++;
    for (let d = 0; d <= 9; d++) {
      const next = value * 10 + d;
      if (next > n) break;
      if (used[d]) continue;
      used[d] = true;
      extend(next);
      used[d] = false;
    }
  };
  for (let first = 1; first <= 9 && first <= n; first++) {
    used[first] = true;
    extend(first);
    used[first] = false;
  }
  return total;
}

