  if (size === 'large') {
    const pick = rand();
    if (pick < 0.25) return [int(1000000000, 2000000000)];
    if (pick < 0.5) return [Math.min(2000000000, 10 ** int(1, 9) - int(0, 2))];
    return [int(1, 2000000000)];
  }
  const pick = rand();
  if (pick < 0.4) return [int(1, 150)];
  if (pick < 0.7) return [int(1, 5000)];
  return [int(1, 300000)];
